def countLongestIncreasing(nums):
    M = 1000000007
    n = len(nums)
    length = [1] * n
    count = [1] * n
    for i in range(n):
        x = nums[i]
        li, ci = 1, 1
        for j in range(i):
            if nums[j] < x:
                cand = length[j] + 1
                if cand > li:
                    li, ci = cand, count[j]
                elif cand == li:
                    ci += count[j]
        length[i] = li
        count[i] = ci % M
    best = max(length)
    return sum(count[i] for i in range(n) if length[i] == best) % M
